class PanelQuad
{
public:
	virtual void TurnOn(bool on);
};

class NameEntryMenu
{
private:
	PanelQuad* box[9];
	PanelQuad* line;
	PanelQuad* name_box[3];
	PanelQuad* keys[41][2];

public:
	void TurnNameEntry(bool on);
};

void NameEntryMenu::TurnNameEntry(bool on)
{
	for(int i=0; i<9; i++)
		box[i]->TurnOn(on);
	for(int i=0; i<3; i++)
		name_box[i]->TurnOn(on);
	line->TurnOn(on);
	for(int i=0; i<41; i++)
	{
		keys[i][0]->TurnOn(on);
		keys[i][1]->TurnOn(false);
	}
}
